using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using StockManagement.Data;using StockManagement.Models;
namespace StockManagement.Controllers;[Authorize(Roles=Roles.Admin+","+Roles.Manager+","+Roles.Staff)] public class CustomersController:Controller{readonly ApplicationDbContext _db;public CustomersController(ApplicationDbContext db)=>_db=db;public IActionResult Index()=>View(_db.Customers.OrderBy(x=>x.Name).ToList());public IActionResult Create()=>View(new Customer());[HttpPost,ValidateAntiForgeryToken]public IActionResult Create(Customer c){if(!ModelState.IsValid)return View(c);_db.Customers.Add(c);_db.SaveChanges();return RedirectToAction(nameof(Index));}public IActionResult Edit(int id){var c=_db.Customers.Find(id);return c==null?NotFound():View(c);}[HttpPost,ValidateAntiForgeryToken]public IActionResult Edit(Customer c){if(!ModelState.IsValid)return View(c);var e=_db.Customers.Find(c.Id);if(e==null)return NotFound();e.Name=c.Name;e.Email=c.Email;e.Phone=c.Phone;_db.SaveChanges();return RedirectToAction(nameof(Index));}[HttpPost,ValidateAntiForgeryToken]public IActionResult Delete(int id){var c=_db.Customers.Find(id);if(c!=null){_db.Customers.Remove(c);try{_db.SaveChanges();}catch{TempData["Error"]="Customer is referenced by a sale.";}}return RedirectToAction(nameof(Index));}}
